-- MANOHAR MOBILE SHOP - SUPABASE SQL
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, email text, address text, city text, pin text, landmark text, role text not null default 'customer' check (role in ('customer','admin')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders (id bigint generated by default as identity primary key, order_id text unique not null, customer_id uuid not null references auth.users(id) on delete cascade, customer_name text not null, customer_phone text not null, address text not null, city text not null, pin text not null, landmark text, items jsonb not null, total numeric(12,2) not null default 0, status text not null default 'New', payment_method text not null default 'cod' check (payment_method in ('cod','upi')), payment_status text not null default 'pending' check (payment_status in ('pending','submitted','verified','rejected')), upi_transaction_id text, payment_status_verified_at timestamptz, tracking_number text, admin_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.orders add column if not exists upi_transaction_id text;
alter table public.orders add column if not exists admin_note text;
alter table public.orders drop constraint if exists orders_payment_method_check;
alter table public.orders add constraint orders_payment_method_check check (payment_method in ('cod','upi'));
alter table public.orders drop constraint if exists orders_payment_status_check;
alter table public.orders add constraint orders_payment_status_check check (payment_status in ('pending','submitted','verified','rejected'));
create index if not exists orders_customer_id_idx on public.orders(customer_id);
create index if not exists orders_created_at_idx on public.orders(created_at desc);
create index if not exists orders_payment_status_idx on public.orders(payment_status);
alter table public.profiles enable row level security; alter table public.orders enable row level security;
create or replace function public.is_admin() returns boolean language sql security definer set search_path=public stable as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
drop policy if exists "profiles own select" on public.profiles; create policy "profiles own select" on public.profiles for select to authenticated using (id=auth.uid() or public.is_admin());
drop policy if exists "profiles own insert" on public.profiles; create policy "profiles own insert" on public.profiles for insert to authenticated with check (id=auth.uid());
drop policy if exists "profiles own update" on public.profiles; create policy "profiles own update" on public.profiles for update to authenticated using (id=auth.uid() or public.is_admin()) with check (id=auth.uid() or public.is_admin());
drop policy if exists "orders customer select" on public.orders; create policy "orders customer select" on public.orders for select to authenticated using (customer_id=auth.uid() or public.is_admin());
drop policy if exists "orders customer insert" on public.orders; create policy "orders customer insert" on public.orders for insert to authenticated with check (customer_id=auth.uid());
drop policy if exists "orders customer update payment" on public.orders; create policy "orders customer update payment" on public.orders for update to authenticated using (customer_id=auth.uid() or public.is_admin()) with check (customer_id=auth.uid() or public.is_admin());
drop policy if exists "orders admin update" on public.orders; create policy "orders admin update" on public.orders for update to authenticated using (public.is_admin()) with check (public.is_admin());
